get_money_amount(N) -> Cache = ets:new(guess_costs, [set, private]), Answer = cost(1, N, Cache), ets:delete(Cache), Answer. cost(Left, Right, _) when Left >= Right -> 0; cost(Left, Right, Cache) -> case ets:lookup(Cache, {Left, Right}) of [{_, Value}] -> Value; [] -> Best = lists:min([Guess + max(cost(Left, Guess - 1, Cache), cost(Guess + 1, Right, Cache)) || Guess <- lists:seq(Left, Right - 1)]), ets:insert(Cache, {{Left, Right}, Best}), Best end.
